from __future__ import absolute_import

from taf.selenium.gnb.oam.coam.vdu.pages import v25R3
import time
from selenium.webdriver.common.by import By
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(v25R3.Diagnostic):
    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"Antenna Line Online Monitoring":
                                        AntennaLineOnlineMonitoringPageV26R2(driver, version)})


class AntennaLineOnlineMonitoringPageV26R2(v25R3.AntennaLineOnlineMonitoringPageV25R3):

    def __init__(self, driver, version):
        super(AntennaLineOnlineMonitoringPageV26R2, self).__init__(driver, version)
        self._view_panel = AntennaLineOnlineMonitoringPageViewPanelV26R2(driver, version)

    def get_antenna_monitoring_results(self, timeout=60):
        return self._view_panel.get_antenna_monitoring_results(timeout)


class AntennaLineOnlineMonitoringPageViewPanelV26R2(v25R3.AntennaLineOnlineMonitoringPageViewPanelV25R3):

    def __init__(self, driver, version):
        super(AntennaLineOnlineMonitoringPageViewPanelV26R2, self).__init__(driver, version)


    def get_antenna_monitoring_results(self, timeout=60):
        """
        Gets the monitoring results for the specified antennas.

        :param timeout: int, timeout for the element to be available
        :return: dict, dictionary with section header text as key and measurements
        """
        results = {}

        sections = [
            ("VSWR", self.locator.HEADERVSWR_HEADER, self.locator.SECTIONVSWR_TABLE,
             self.locator.HEADERSVSWR_HEADERS, self.locator.ROWSVSWR_ROWS),
            ("RSSI", self.locator.RSSI_HEADER, self.locator.RSSI_TABLE,
             self.locator.RSSI_HEADERS, self.locator.RSSI_ROWS),
            ("RTWP", self.locator.RTWP_HEADER, self.locator.RTWP_TABLE,
             self.locator.RTWP_HEADERS, self.locator.RTWP_ROWS),
            ("ETP", self.locator.ETP_HEADER, self.locator.ETP_TABLE,
             self.locator.ETP_HEADERS, self.locator.ETP_ROWS),
        ]

        for section_name, header_xpath, table_xpath, headers_xpath, cells_xpath in sections:
            section_header_text = section_name
            try:
                if not self.element_exists(header_xpath, timeout=timeout):
                    logger.warning(f"{section_name} header not found")
                    continue

                header_element = self.get_all_matching_elements(header_xpath)[0]
                parent_header = header_element.find_element(By.XPATH,
                                                            "./ancestor::div[contains(@class, 'p-accordion-header')]")
                section_header_text = parent_header.text.strip()

                if not self.element_exists(table_xpath, timeout=3):
                    logger.warning(f"{section_name} table not visible")
                    results[section_header_text] = {"error": "Table not visible"}
                    continue

                time.sleep(0.5)
                if not self.element_exists(headers_xpath, timeout=2):
                    logger.warning(f"No column headers found for {section_name}")
                    results[section_header_text] = {"error": "No column headers"}
                    continue

                header_elements = self.get_all_matching_elements(headers_xpath)
                column_names = [h.text.strip() for h in header_elements if h.text.strip()]

                cell_values = self._extract_table_data(table_xpath, column_names, section_name)

                results[section_header_text] = self._map_antenna_table_generic(column_names, cell_values)

            except Exception as e:
                logger.error(f"Error processing {section_name}: {str(e)}")
                results[section_header_text] = {"error": str(e)}

        return results

    def _extract_table_data(self, table_xpath, column_names, section_name):  # noqa: C901
        """
        Extract table data handling rowspan and colspan attributes.

        :param table_xpath: XPath to the table
        :param column_names: List of column header names
        :param section_name: Name of the section for logging
        :return: List of cell values or dict with message if no data
        """
        rows_xpath = table_xpath + "//tbody//tr"

        if not self.element_exists(rows_xpath, timeout=2):
            return []

        row_elements = self.get_all_matching_elements(rows_xpath)

        if len(row_elements) == 1:
            first_row_text = row_elements[0].text.strip().lower()
            if "no data" in first_row_text:
                logger.info(f"{section_name}: No data available")
                return {"message": "No data available"}

        num_columns = len(column_names)
        grid = [[None] * num_columns for _ in row_elements]

        for row_idx, row_element in enumerate(row_elements):
            cells_in_row = row_element.find_elements(By.XPATH, ".//td")
            col_idx = 0

            for cell in cells_in_row:
                while col_idx < num_columns and grid[row_idx][col_idx] is not None:
                    col_idx += 1

                if col_idx >= num_columns:
                    break

                cell_text = cell.text.strip()
                rowspan = int(cell.get_attribute("rowspan") or 1)
                colspan = int(cell.get_attribute("colspan") or 1)

                for r in range(rowspan):
                    for c in range(colspan):
                        if row_idx + r < len(grid) and col_idx + c < num_columns:
                            grid[row_idx + r][col_idx + c] = cell_text if r == 0 else ""

                col_idx += colspan

        return [cell for row in grid for cell in row]

    @staticmethod
    def _map_antenna_table_generic(column_names, cell_values):   # noqa: C901
        """
        Generic table mapping for antenna measurements.

        :param column_names: list of column header names
        :param cell_values: list of all cell values row-wise

        :return: dict in format {"measurements": {<unique_key>: {metadata + timestamps}}}
        """
        if isinstance(cell_values, dict):
            return {**cell_values, "measurements": {}}

        num_columns = len(column_names)
        if num_columns == 0:
            return {"error": "No columns found"}

        source_col_index = next((i for i, col in enumerate(column_names) if col.lower() == "source"), None)

        if source_col_index is None:
            logger.warning("No 'Source' column found in headers")

        rows = [cell_values[i:i + num_columns] + [""] * max(0, num_columns - len(cell_values[i:i + num_columns]))
                for i in range(0, len(cell_values), num_columns)]

        last = [""] * num_columns
        resolved_rows = []

        for row in rows:
            resolved = []
            skip_row = False

            for col_idx in range(num_columns):
                val = row[col_idx].strip() if col_idx < len(row) and row[col_idx] else ""

                if col_idx == source_col_index:
                    if val:
                        resolved.append(val)
                        last[col_idx] = val
                    else:
                        skip_row = True
                        break
                else:
                    resolved.append(val or last[col_idx])
                    if val:
                        last[col_idx] = val

            if not skip_row and len(resolved) == num_columns:
                resolved_rows.append(resolved)

        measurements = {}

        for row in resolved_rows:
            key = row[source_col_index] if source_col_index is not None and source_col_index < len(row) else ""

            if not key:
                non_empty = [val for val in row if val]
                if not non_empty:
                    continue
                key = non_empty[0]

            measurements[key] = {
                col_name: (row[i] if i < len(row) and row[i] else "-")
                for i, col_name in enumerate(column_names)
            }

        return {"measurements": measurements}
